function parsep($u){$h=getx($u);$ti=titlex($h);if($ti===''||preg_match('/^\d+$/',trim($ti)))return null;$t=txt($h);$it=items($t);if(!$it||!preg_match('/(?:W\s*\/\s*S\s*\/\s*G|S\s*\/\s*W\s*\/\s*G)\s*:/iu',$t))return null;return['url'=>$u,'title'=>$ti,'items'=>$it,'images'=>imgs($h)];}
function catid(){ $n='ASM Meble';$t=term_exists($n,'product_cat');if(is_array($t))return(int)$t['term_id'];if(is_int($t))return$t;$r=wp_insert_term($n,'product_cat');return is_wp_error($r)?0:(int)$r['term_id'];}
function mediaids($urls,$post){global $skip;static $cache=[];if($skip)return[];$o=[];foreach($urls as $u){if(isset($cache[$u])){$o[]=$cache[$u];continue;}$id=media_sideload_image($u,$post,null,'id');if(is_wp_error($id)){aw("Image skipped: ".$id->get_error_message());continue;}$cache[$u]=(int)$id;$o[]=(int)$id;}return array_values(array_unique($o));}

al('ASM Meble -> Decora Home WooCommerce');
al('Selling-price SKU loaded: '.count($prices));
if($dry)aw('DRY RUN - no writes');
$urls=leaves(); al('Leaf ASM pages: '.count($urls));
$map=[];$pages=[];$valid=0;
foreach($urls as $i=>$u){try{$p=parsep($u);if(!$p)continue;$valid++;$pages[$u]=$p;foreach($p['items'] as $s=>$d)$map[sku_n($s)]=$u;}catch(Throwable $e){aw('Skip '.$u.' — '.$e->getMessage());}if(($i+1)%20===0)al('Scanned '.($i+1).'/'.count($urls).' | valid '.$valid.' | SKU '.count($map));}
al('Valid product pages: '.$valid); al('Website SKU mapped: '.count($map));
$cat=catid();$created=0;$updated=0;$missing=0;$errors=0;$matched=0;$pm=[];
foreach($prices as $sku=>$sale){$sku=sku_n($sku);$u=$map[$sku]??null;if(!$u||!isset($pages[$u])){$missing++;continue;}$matched++;$p=$pages[$u];$info=$p['items'][$sku]??['dimensions'=>'','finish'=>''];$name=trim($p['title']);if(count($p['items'])>1)$name.=' – '.$sku;$existing=wc_get_product_id_by_sku($sku);$new=!$existing;if($dry){al(($new?'[CREATE] ':'[UPDATE] ').$sku.' | '.$name.' | '.$sale.' EUR');continue;}try{$pr=$existing?wc_get_product($existing):new WC_Product_Simple();if(!$pr)throw new RuntimeException('Product init failed');$pr->set_name($name);if($new){$pr->set_sku($sku);$pr->set_status('draft');$pr->set_manage_stock(false);$pr->set_stock_status('outofstock');}$pr->set_regular_price(wc_format_decimal((float)$sale,2));$pr->set_price(wc_format_decimal((float)$sale,2));$desc='<p><strong>'.esc_html($name).'</strong> — mobilier ASM Meble sélectionné par Decora Home.</p><ul><li><strong>Référence :</strong> '.esc_html($sku).'</li>';if(!empty($info['finish']))$desc.='<li><strong>Finition :</strong> '.esc_html($info['finish']).'</li>';if(!empty($info['dimensions']))$desc.='<li><strong>Dimensions :</strong> '.esc_html($info['dimensions']).'</li>';$desc.='</ul><p>Source fabricant : ASM Meble.</p>';$pr->set_description($desc);$pr->set_short_description('<strong>ASM Meble</strong> · Réf. '.esc_html($sku).(!empty($info['dimensions'])?' · '.esc_html($info['dimensions']):''));if($cat)$pr->set_category_ids([$cat]);$id=$pr->save();if(!$id)throw new RuntimeException('Save failed');update_post_meta($id,'_asm_source_url',esc_url_raw($u));update_post_meta($id,'_asm_dimensions',sanitize_text_field($info['dimensions']??''));update_post_meta($id,'_asm_finish',sanitize_text_field($info['finish']??''));update_post_meta($id,'_asm_supplier','ASM Meble');if(!isset($pm[$u]))$pm[$u]=mediaids($p['images'],$id);$mi=$pm[$u];if($mi){$pr=wc_get_product($id);if(!$pr->get_image_id())$pr->set_image_id($mi[0]);if(!$pr->get_gallery_image_ids()&&count($mi)>1)$pr->set_gallery_image_ids(array_slice($mi,1));$pr->save();}if($new)$created++;else$updated++;if(($created+$updated)%25===0)al('Imported '.($created+$updated).' matched products');}catch(Throwable $e){$errors++;aw($sku.' failed: '.$e->getMessage());}}
al('');al('=== ASM IMPORT SUMMARY ===');al('Price SKU: '.count($prices));al('Matched: '.$matched);al('Created: '.$created);al('Updated: '.$updated);al('Not found: '.$missing);al('Errors: '.$errors);WP_CLI::success($dry?'Dry run complete':'ASM import complete');
